import java.util.*;class TaskBinding{static Object customer(long id,String last,String first,String middle,String card){return new Customer(id,last,first,middle,"Учебный адрес",card,"Счёт"+id);}static Object shortValue(long id,String surname){return new Customer(id,surname);}static Object[]array(Object...a){return Arrays.copyOf(a,a.length,Customer[].class);}static Object[]sorted(Object[]a){return Customer.sorted((Customer[])a);}static Object[]range(Object[]a,String lo,String hi){return Customer.range((Customer[])a,lo,hi);}static List<?>value(Object x){Customer c=(Customer)x;return List.of(c.id(),c.last(),c.first(),c.middle(),c.address(),c.card(),c.account());}static void edit(Object x,long id,String last,String first,String middle,String address,String card,String account){Customer c=(Customer)x;c.id(id);c.last(last);c.first(first);c.middle(middle);c.address(address);c.card(card);c.account(account);}static String text(Object x){return x.toString();}}
